components:
/* Component treatment example: round the message composer and tint the
   text selection. Prefer stable selectors ([contenteditable], ::selection);
   hashed class names change between upstream releases. */
#root [contenteditable="true"], #root textarea { border-radius: 14px; }
#root :focus-visible { outline-color: var(--dsw-alias-brand-primary, rgb(196,92,58)); }
#root ::selection { background: rgba(196, 92, 58, 0.20); }

motion:
/* Motion example: a slow, decorative ambient drift. Automatically disabled
   under prefers-reduced-motion and the Appearance > Motion toggle. */
@keyframes hd-starter-drift { from { background-position: 0 0; } to { background-position: 0 80px; } }
#root > * { animation: hd-starter-drift 26s linear infinite; }
